# Fix the value transformation
def transform_inmono(grid):
    if not grid or not grid[0]:
        return grid

    H, W = len(grid), len(grid[0])
    result = [[0] * W for _ in range(H)]

    center_y, center_x = (H - 1) / 2, (W - 1) / 2

    for y in range(H):
        for x in range(W):
            val = grid[y][x]

            # Keep 2s in place
            if val == 2:
                result[y][x] = 2
                continue

            if val == 0:
                continue

            # Value transformation: 3->8, 6->3, 7->6, 8->7
            val_map = {3: 8, 6: 3, 7: 6, 8: 7}
            new_val = val_map[val]

            # Direction based on position relative to center
            if y < center_y:
                if x < center_x:
                    dy, dx = -1, -1  # up-left
                else:
                    dy, dx = -1, 1  # up-right
            else:
                if x < center_x:
                    dy, dx = 1, -1  # down-left
                else:
                    dy, dx = 1, 1  # down-right

            # Draw diagonal, length = original value
            length = val
            ny, nx = y, x
            for i in range(length):
                result[ny][nx] = new_val
                ny += dy
                nx += dx
                if ny < 0 or ny >= H or nx < 0 or nx >= W:
                    break

    return result

