    """Simulate with explicit overlap resolution rules"""
    H, W = len(grid), len(grid[0])
    val_map = {3: 8, 6: 3, 8: 7, 7: 6}

    # For each cell, collect all contributions
    contributions = [[[] for _ in range(W)] for _ in range(H)]

    for y in range(H):
        for x in range(W):
            val = grid[y][x]
            if val == 0 or val == 2:
                continue

            new_val = val_map[val]
            center_y, center_x = (H - 1) / 2, (W - 1) / 2

            if y < center_y:
                if x < center_x:
                    dy, dx = -1, -1
                else:
                    dy, dx = -1, 1
            else:
                if x < center_x:
                    dy, dx = 1, -1
                else:
                    dy, dx = 1, 1

            cy, cx = y, x
            while val > 0 and cy >= 0 and cy < H and cx >= 0 and cx < W:
                contributions[cy][cx].append((y, x, new_val, val))
                val -= 1
                cy += dy
                cx += dx

    # Now resolve conflicts: for each cell, if multiple diagonals contribute,
    # use the source with the LARGEST original value

    result = [[0] * W for _ in range(H)]

    for y in range(H):
        for x in range(W):
            sources = contributions[y][x]
            if not sources:
                # Keep as 0 (or 2 for the 2x2 block)
                if grid[y][x] == 2:
                    result[y][x] = 2
                else:
                    result[y][x] = 0
                continue

            # For overlap: if multiple sources, pick one
            # Try: largest original value wins
            sources_sorted = sorted(sources, key=lambda s: s[3], reverse=True)
            # winner = max(sources, key=lambda s: s[3])
            result[y][x] = sources_sorted[0][2]

    return result

